function handleFirstLevel(index, name) {//点击一级分类
    firstType.value = name;
}

function handleSecondLevel(index, name, item) {//点击二级分类
    item.visible[index] = !item.visible[index]
    secondType.value = name;
    if (item.data[index].length === 0) {
        postHeritageApi(firstType.value, secondType.value).then(res => {
            item.data[index] = res.data.data;
        })
    }

}

function firstLevelColor(index) {//计算背景颜色
    const colors = ['rgba(156, 104, 52, 0.71)', 'rgba(29, 70, 128, 0.69)', 'rgba(151, 39, 90, 0.67)'];
    return colors[index % colors.length];
}

function secondLevelColor(index) {//计算背景颜色
    const colors = ['rgba(182, 145, 108, 0.45)', 'rgba(96, 125, 164, 0.45)', 'rgba(182, 107, 141, 0.45)'];
    return colors[index % colors.length];
}

function svgColor(index) {//计算背景颜色
    const colors = ['rgba(184, 127, 55, 1)', 'rgba(96, 125, 164, 1)', 'rgba(182, 107, 141, 1)'];
    return colors[index % colors.length];
}

/*detail*/
const showProject = ref(false);
const decodedContent = ref('');
function showDetail(data) {
    showProject.value = true;
    console.log(data);
    const content = data.content;
    decodedContent.value = content.replace(/&lt;/g, '<').replace(/&gt;/g, '>');
}
</script>

<template>
    <el-tabs tab-position="bottom" v-model="chartName" class="chart" @tab-click="handleClick">
        <el-tab-pane label="各门类数目一览" name="first">
            <el-image class="chart-img" src="/icon/first.jpg" :preview-src-list="['/icon/first.jpg']" />
        </el-tab-pane>
        <el-tab-pane label="申报数量变化" name="second">
            <el-image class="chart-img" src="/icon/second.jpg" :preview-src-list="['/icon/second.jpg']" />
        </el-tab-pane>
        <el-tab-pane label="各省分部占比" name="third">
            <el-image class="chart-img" src="/icon/third.png" :preview-src-list="['/icon/third.png']" />
        </el-tab-pane>
        <el-tab-pane label="各类非遗传承人人数变化" name="fourth">
            <el-image class="chart-img" src="/icon/fourth.png" :preview-src-list="['/icon/fourth.png']" />
        </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="showProject" fullscreen style="background-image: url('/icon/dialogBackground.svg');background-size: cover;
    background-position: center;
    background-repeat: no-repeat;">
        <div v-html="decodedContent" class="dialog-project">
        </div>
        <div style="text-align: center;margin: 10px 0;">
            <span v-if="!decodedContent">暂无内容</span>
            <span v-else>到底了</span>
        </div>
    </el-dialog>
